int PqInt8Quantizer::train(IndexHolder::Pointer holder) {
  if (!holder) {
    return kErrUnsupported;
  }

  const size_t input_count = holder->count();
  const uint32_t elem_size = element_size();
  const size_t vec_bytes = static_cast<size_t>(original_dim_) * elem_size;
  if (!input_count || holder->dimension() != original_dim_ ||
      holder->element_size() != vec_bytes ||
      holder->data_type() != (input_data_type_ == DataType::kFp16
                                  ? IndexMeta::DataType::DT_FP16
                                  : IndexMeta::DataType::DT_FP32)) {
    return kErrUnsupported;
  }
  size_t num = std::min(input_count, static_cast<size_t>(kMaxTrainVectors));
  if (num > std::numeric_limits<size_t>::max() / vec_bytes) {
    return kErrUnsupported;
  }

  std::vector<uint8_t> all_data;
  if (!CollectPqTrainingSamples(holder, kMaxTrainVectors, vec_bytes,
                                &all_data)) {
    return kErrUnsupported;
  }
  holder.reset();

  size_t data_stride = original_dim_ * elem_size;

  // For Cosine: normalize training data so centroids are learned in
  // normalized space (L2 minimization == maximizing cosine similarity).
  if (meta_.metric_name() == "Cosine") {
    switch (input_data_type_) {
      case DataType::kFp16:
        normalize(reinterpret_cast<ailego::Float16 *>(all_data.data()), num);
        break;
      case DataType::kFp32:
        normalize(reinterpret_cast<float *>(all_data.data()), num);
        break;
      default:
        break;
    }
  }

  // Zero-mean centering: subtract the per-dimension mean; the centroid is
  // saved for quantize_data / quantize_query / dequantize.  For Cosine this
  // runs AFTER normalization, so all paths keep the same order
  // (normalize -> center; dequantize: un-center -> rescale).
  if (use_zero_mean_) {
    switch (input_data_type_) {
      case DataType::kFp16:
        compute_and_subtract_center(
            reinterpret_cast<ailego::Float16 *>(all_data.data()), num);
        break;
      case DataType::kFp32:
        compute_and_subtract_center(reinterpret_cast<float *>(all_data.data()),
                                    num);
        break;
      default:
        break;
    }
  }

  opq_.train(
      all_data.data(), num, "PqInt8Quantizer",
      [&](uint32_t max_iters) {
        train_all_chunks(all_data.data(), num, data_stride, max_iters);
        build_centroid_ptrs_cache();
      },
      [this](const float *rotated, size_t count, float *x_hat) {
        return encode_reconstruct_batch(rotated, count, x_hat);
      });

  train_all_chunks(all_data.data(), num, data_stride, kMaxKmeansIters);

  // Pre-build centroid pointer cache (needed by compute_dist_table).
  build_centroid_ptrs_cache();

  // Pre-compute SDC dist_table.
  compute_dist_table();

  // Pre-compute sub-centroid norms for the precomputed residual table.
  compute_sub_centroid_norms();

  return 0;
}

void PqInt8Quantizer::train_all_chunks(const void *data, size_t num,
                                       size_t stride, uint32_t max_iters) {
  // Create thread pool.
  auto threads =
      std::make_shared<SingleQueueIndexThreads>(thread_count_, false);
  auto task_group = threads->make_group();

  // Distribute chunks across threads, dispatched by data type.
  std::atomic<size_t> finished{0};
  size_t pool_count = threads->count();

  auto submit_training = [&](const auto *typed_data) {
    using T = std::remove_const_t<std::remove_pointer_t<decltype(typed_data)>>;
    for (size_t i = 0; i < pool_count; ++i) {
      task_group->submit(
          ailego::Closure::New([this, typed_data, num, stride, i, pool_count,
                                max_iters, &finished]() {
