62	  cpu_set_t allowed_mask;
63	  if (!GetAllowedCpuMask(&allowed_mask)) {
64	    return;
65	  }
66	
67	  for (size_t i = 0u; i < pool.size(); ++i) {
68	    const int error = pthread_setaffinity_np(
69	        pool[i].native_handle(), sizeof(allowed_mask), &allowed_mask);
70	    if (error != 0) {
