85	uint32_t SafeWorkerCount() noexcept {
86	  return std::max(std::thread::hardware_concurrency(), 1u);
87	}
88	
89	}  // namespace
90	
91	ThreadPool::ThreadPool() : ThreadPool(SafeWorkerCount(), false) {}
92	
93	ThreadPool::ThreadPool(uint32_t size, bool binding) {
94	  const uint32_t max_size = SafeWorkerCount();
95	  const uint32_t safe_size = std::min(std::max(size, 1u), max_size);
96	  if (safe_size != size) {
97	    LOG_WARN(
98	        "ThreadPool worker count[%u] is outside supported range[1, %u], "
99	        "clamped to %u",
100	        size, max_size, safe_size);
101	  }
102	
103	  try {
104	    // Avoid vector reallocations after workers have started. If thread creation
105	    // still fails, stop and join the workers already created before rethrowing.
106	    pool_.reserve(safe_size);
107	    for (uint32_t i = 0u; i < safe_size; ++i) {
108	      pool_.emplace_back(&ThreadPool::worker, this);
109	    }
110	    if (binding) {
111	      this->bind();
112	    }
113	  } catch (...) {
114	    this->stop();
115	    for (auto &worker : pool_) {
116	      if (worker.joinable()) {
117	        worker.join();
118	      }
119	    }
120	    throw;
121	  }
122	}
